const express = require('express');
const multer = require('multer');
const { fork } = require('child_process');
const path = require('path');

const app = express();
const upload = multer({ dest: 'uploads/' });

app.post('/import-customers', upload.single('csv'), (req, res) => {
    const csvFilePath = path.join(__dirname, req.file.path);
    const adminEmail = req.body.adminEmail;

    // Fork a child process for background processing
    const worker = fork('worker.js');

    worker.send({
        csvPath: csvFilePath,
        dbConfig: process.env.DB_CONFIG,
        adminEmail: adminEmail
    });

    // Handle messages from child process
    worker.on('message', (msg) => {
        if (msg.status === 'started') {
            console.log('Import started');
        }
    });

    // Handle errors
    worker.on('error', (err) => {
        console.error('Worker error:', err);
    });

    // Handle exit
    worker.on('exit', (code) => {
        console.log(`Worker exited with code ${code}`);
    });

    res.status(202).json({
        status: 'Import started in background',
        fileId: req.file.filename
    });
});

app.listen(3000, () => console.log('Server running on port 3000'));

