// Batch insert function
const insertBatch = async (client, batch) => {
    if (batch.length === 0) return;

    const columns = Object.keys(batch[0]).join(', ');
    const values = batch.map((row, i) => 
        `(${Object.values(row).map((_, j) => 
            `$${i * Object.keys(row).length + j + 1}`
        ).join(', ')})`
    ).join(', ');

    const flatValues = batch.flatMap(Object.values);

    try {
        await client.query(`INSERT INTO customers (${columns}) VALUES ${values}`, flatValues);
    } catch (err) {
        throw err;
    }
};

// Main processing function
const processCSV = async (csvPath, dbConfig, adminEmail) => {
    const client = new Client(JSON.parse(dbConfig));
    const batchSize = 500;

    try {
        await client.connect();

        const stream = fs.createReadStream(csvPath);
        const batch = [];

        papaparse.parse(stream, {
            header: true,
            skipEmptyLines: true,
            step: async (results, parser) => {
                batch.push(results.data);

                if (batch.length >= batchSize) {
                    await insertBatch(client, batch);
                    batch.length = 0; // Clear batch
                }
            },
            complete: async () => {
                if (batch.length > 0) {
                    await insertBatch(client, batch);
                }

                await sendNotification(true);
                await client.end();

                // Notify parent process
                if (process.send) {
                    process.send({ status: 'completed' });
                }
            },
            error: async (err) => {
                await sendNotification(false, err.message);
                await client.end();

                // Notify parent process
                if (process.send) {
                    process.send({ status: 'error', error: err.message });
                }
            }
        });

    } catch (err) {
        await sendNotification(false, err.message);
        await client.end();

        // Notify parent process
        if (process.send) {
            process.send({ status: 'error', error: err.message });
        }
    }
};

