        }

        neurons_.push_back(neuron);
        int id = next_id_++;
        neuron->set_neuron_id(id);
        neuron_map_[id] = neuron;
        return id;
    }

    // Connect two neurons in the network
    bool connect_neurons(int pre_id, int post_id, double weight = 1.0, double reciprocal_weight = 0.0) {
        auto pre_it = neuron_map_.find(pre_id);
        auto post_it = neuron_map_.find(post_id);

        if (pre_it == neuron_map_.end() || post_it == neuron_map_.end()) {
            return false;
        }

        // Connect the neurons
        pre_it->second->connect_output(post_it->second, weight);
        post_it->second->connect_input(pre_it->second, weight);

        // If reciprocal weight is specified, create a reciprocal connection
        if (reciprocal_weight > 0) {
            post_it->second->connect_output(pre_it->second, reciprocal_weight);
            pre_it->second->connect_input(post_it->second, reciprocal_weight);
        }

        return true;
    }

