    bool disconnect_neurons(int pre_id, int post_id) {
        auto pre_it = neuron_map_.find(pre_id);
        auto post_it = neuron_map_.find(post_id);

        if (pre_it == neuron_map_.end() || post_it == neuron_map_.end()) {
            return false;
        }

        // Disconnect the neurons
        bool input_disconnected = post_it->second->disconnect_input(pre_it->second);
        bool output_disconnected = pre_it->second->disconnect_output(post_it->second);

        return input_disconnected && output_disconnected;
    }

    // Run the simulation for a specified duration
    void run_simulation(double duration, double external_input = 0.0) {
        if (duration <= 0) {
            throw std::invalid_argument("Simulation duration must be positive");
        }

        int steps = static_cast<int>(duration / dt_);

        for (int i = 0; i < steps; ++i) {
            // Update all neurons
            for (auto& neuron : neurons_) {
                neuron->update(dt_, external_input);
            }
        }
    }

