% === Braking Torque Function ===
function torque = braking_torque(t, t_start, slope, torque_max)
    % Calculate braking torque as a ramp function with saturation
    if t >= t_start
        % Use ramp signal after t_start
        torque = ramp_signal(t - t_start, slope);
        % Limit to maximum torque
        torque = min(torque, torque_max);
    else
        torque = 0;
    end
end

% === Ramp Signal Function ===
function signal = ramp_signal(t, slope)
    % Generate a linearly increasing ramp signal
    signal = slope * t;
end

% === Tire Model ===
function mu = tire_model(slip, mu_max, s_max)
    if slip > 0
        mu = mu_max * (1 - exp(-s_max/slip));
    else
        mu = 0;
    end
end

% === Slip Calculation ===
function slip = calculate_slip(v_vehicle, v_wheel)
    if v_vehicle <= 0
        slip = 0;
    else
        slip = (v_vehicle - v_wheel) / v_vehicle;
    end
end

% === ABS Control Logic ===
function mod = abs_cycle(slip, threshold)
    if slip > threshold
        mod = 0.5;  % Reduce torque to allow wheel recovery
    else
        mod = 1.0;  % Apply full torque for maximum braking
    end
end

% === Wheel Dynamics ===
function dydt = wheel_dynamics(t, y, params)
    v_vehicle = y(1);
    v_wheel = y(2);
    omega = y(3);

    % Calculate slip
    slip = calculate_slip(v_vehicle, v_wheel);

    % Tire force
    mu = tire_model(slip);
    Fx = mu * params.Fz;

    % Braking torque with ABS modulation
    T_brake = braking_torque(t, params.t_start, params.slope, params.torque_max) * abs_cycle(slip);

    % Equations of motion
    dv_vehicle = -Fx / params.m;
    domega = (Fx * params.R - T_brake) / params.I;

    dydt = [dv_vehicle; dv_vehicle; domega];
end

% === Visualization Function ===
function visualize_results(t, v_vehicle, v_wheel, slip, mu, torque)
    % Create animated visualization
    figure;
    h = animatedline('Color', 'b');
    h2 = animatedline('Color', 'r');
    axis([0 t(end) 0 max([v_vehicle; v_wheel])]);
    xlabel('Time (s)');
    ylabel('Speed (m/s)');
    title('Vehicle and Wheel Speeds');
    legend('Vehicle Speed', 'Wheel Speed');
    grid on;

    for k = 1:length(t)
        addpoints(h, t(k), v_vehicle(k));
        addpoints(h2, t(k), v_wheel(k));
        drawnow limitrate;
    end

    % Create standard plots
    figure;
    subplot(2,2,1);
    plot(t, v_vehicle, 'b', t, v_wheel, 'r');
    title('Speeds (m/s)');
    xlabel('Time (s)');
    legend('Vehicle', 'Wheel');

    subplot(2,2,2);
    plot(t, slip, 'g');
    title('Slip Ratio');
    xlabel('Time (s)');

    subplot(2,2,3);
    plot(t, mu, 'm');
    title('Friction Coefficient');
    xlabel('Time (s)');

    subplot(2,2,4);
